#include "../../common/student_info.h"

#define N 50
int main(void){student_info();int n,m,d[N],used[N]={0},w[N][N],i,j,s,u,v,c;printf("Vertices: ");scanf("%d",&n);if(n<1||n>N)return 1;for(i=0;i<n;i++)for(j=0;j<n;j++)w[i][j]=(i==j)?0:100000000;printf("Edges (u v weight): ");scanf("%d",&m);for(i=0;i<m;i++){scanf("%d%d%d",&u,&v,&c);if(u>=0&&u<n&&v>=0&&v<n&&c>=0)w[u][v]=w[v][u]=c;}printf("Source vertex: ");scanf("%d",&s);if(s<0||s>=n)return 1;for(i=0;i<n;i++)d[i]=w[s][i];used[s]=1;for(i=1;i<n;i++){int best=100000000;u=-1;for(j=0;j<n;j++)if(!used[j]&&d[j]<best){best=d[j];u=j;}if(u<0)break;used[u]=1;for(v=0;v<n;v++)if(!used[v]&&d[u]+w[u][v]<d[v])d[v]=d[u]+w[u][v];}puts("Shortest distances:");for(i=0;i<n;i++)if(d[i]>=100000000)printf("%d: unreachable\n",i);else printf("%d: %d\n",i,d[i]);puts("\nStar graph center is the vertex with degree n-1 (when n>1).");for(i=0;i<n;i++){int degree=0;for(j=0;j<n;j++)if(i!=j&&w[i][j]<100000000)degree++;if(n==1||degree==n-1)printf("Center: %d\n",i);}return 0;}
